import 'dart:async';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/error/app_exception.dart';import '../providers/providers.dart';import '../widgets/content_cards.dart';
class SearchScreen extends ConsumerStatefulWidget{const SearchScreen({super.key});@override ConsumerState<SearchScreen>createState()=>_SearchScreenState();}
class _SearchScreenState extends ConsumerState<SearchScreen>with SingleTickerProviderStateMixin{final input=TextEditingController();String query='';Timer?timer;late final TabController tabs;@override void initState(){super.initState();tabs=TabController(length:2,vsync:this);}void changed(String v){timer?.cancel();timer=Timer(const Duration(milliseconds:450),()=>setState(()=>query=v.trim()));}@override Widget build(BuildContext context){final result=ref.watch(searchProvider(query));return Scaffold(appBar:AppBar(title:const Text('Qidiruv')),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,4,16,10),child:TextField(controller:input,autofocus:false,onChanged:changed,decoration:InputDecoration(hintText:'Kino, kanal, aktyor yoki rejissyor…',prefixIcon:const Icon(Icons.search),suffixIcon:input.text.isEmpty?null:IconButton(onPressed:(){input.clear();setState(()=>query='');},icon:const Icon(Icons.close))))),TabBar(controller:tabs,tabs:const[Tab(text:'🎬  Kinolar'),Tab(text:'📺  Telekanallar')]),Expanded(child:query.length<2?const _Hint():result.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(friendlyError(e))),data:(d)=>TabBarView(controller:tabs,children:[_MovieResults(d['movies']!.cast()),_ChannelResults(d['channels']!.cast())]))) ]));}@override void dispose(){timer?.cancel();input.dispose();tabs.dispose();super.dispose();}}
class _Hint extends StatelessWidget{const _Hint();@override Widget build(BuildContext context)=>const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.manage_search_rounded,size:64,color:Colors.grey),SizedBox(height:14),Text('Kamida 2 ta belgi kiriting'),SizedBox(height:5),Text('Nomi, aktyor, rejissyor, janr va mamlakat bo‘yicha',style:TextStyle(fontSize:12,color:Colors.grey))]));}
class _MovieResults extends StatelessWidget{final List items;const _MovieResults(this.items);@override Widget build(BuildContext context)=>items.isEmpty?const Center(child:Text('Kino topilmadi.')):GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:190,mainAxisExtent:330,crossAxisSpacing:12,mainAxisSpacing:14),itemCount:items.length,itemBuilder:(_,i)=>MovieCard(movie:items[i],width:190));}
class _ChannelResults extends StatelessWidget{final List items;const _ChannelResults(this.items);@override Widget build(BuildContext context)=>items.isEmpty?const Center(child:Text('Telekanal topilmadi.')):GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:210,mainAxisExtent:170,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:items.length,itemBuilder:(_,i)=>ChannelCard(channel:items[i]));}
